--
-- TPS01_LOG_CARDS  (Table)
--
CREATE TABLE REPORT.TPS01_LOG_CARDS
(
  CPS01_SERIAL_NUMBER     VARCHAR2(14 BYTE)     NOT NULL,
  CPS01_PIN_NUMBER        NUMBER(16),
  CPS01_CARD_TYPE         VARCHAR2(3 BYTE)      NOT NULL,
  CPS01_DENOMINATION      NUMBER(5)             NOT NULL,
  CPS01_DATE_GENERATED    DATE                  NOT NULL,
  CPS01_LOG_PHY_IND       VARCHAR2(3 BYTE)      NOT NULL,
  CPS01_CARD_ID           NUMBER(12)            NOT NULL,
  CPS01_OUTLET_CODE       VARCHAR2(10 BYTE)     NOT NULL,
  CPS01_MSISDN            VARCHAR2(13 BYTE),
  CPS01_BATCH_NUMBER      VARCHAR2(11 BYTE),
  CPS01_DATE_SOLD         DATE,
  CPS01_DIST_CHANNEL      VARCHAR2(20 BYTE),
  CPS01_DATE_CEASED       DATE,
  CPS01_DATE_PRINTED      DATE,
  CPS01_DATE_RECHARGE     DATE,
  CPS01_LOGICAL_ORDER_NR  VARCHAR2(20 BYTE),
  CPS01_DATE_AVAILABLE    DATE,
  CPS01_CURRENT_STATUS    NUMBER(2),
  CPS01_ACCESS_CODE       VARCHAR2(16 BYTE)     NOT NULL,
  CPS01_DATE_MODIFIED     DATE                  NOT NULL
)
TABLESPACE PPMS_DATA_04
PARTITION BY RANGE (CPS01_DATE_RECHARGE)
(
