--
-- TPS30_CARD_BOXES  (Table)
--
CREATE TABLE REPORT.TPS30_CARD_BOXES
(
  CPS30_BOX_NUMBER             VARCHAR2(20 BYTE) NOT NULL,
  CPS30_BRICK_NUMBER           VARCHAR2(20 BYTE) NOT NULL,
  CPS30_DENOMINATION_CODE      VARCHAR2(35 BYTE) NOT NULL,
