  CPS6073_ORDER_SUB_TYPE   VARCHAR2(20 BYTE)    NOT NULL,
  CPS6073_FILE_NAME        VARCHAR2(50 BYTE),
  CPS6073_PAYMENT_REF_NUM  VARCHAR2(50 BYTE),
  CPS6073_PAYMENT_AMOUNT   NUMBER(22,2),
  CPS6073_PAYMENT_DATE     DATE,
  CPS6073_BRANCH           VARCHAR2(20 BYTE),
  CPS6073_DEL_ADDRESS      VARCHAR2(20 BYTE),
