  CPS6073_CORELATION_ID    VARCHAR2(20 BYTE),
  CPS6073_CONTRACT         VARCHAR2(20 BYTE)
)
LOB (CPS6073_IMAGE_CONTENT) STORE AS (
  TABLESPACE PPMS_DATA_04
  ENABLE       STORAGE IN ROW
  CHUNK       8192
  RETENTION
  NOCACHE
  LOGGING
  INDEX (TABLESPACE PPMS_DATA_01))
TABLESPACE PPMS_DATA_04
LOGGING
NOCOMPRESS
NOPARALLEL
MONITORING;



